namespace LastRail.Tests.EditMode {
 public class KylePresentationTimelineTests {
  static int[] Idle()=>Enumerable.Repeat(120,12).ToArray();static int[] Attack()=>new[]{100,80,80,60,60,60,80,80,100,100,100,140};
  static CombatUnitAnimationState Cue(string id="original",string motion="attack")=>new CombatUnitAnimationState("op_kyle",CombatUnitRole.Operator,motion,id);
  static KylePresentationTimeline New()=>new KylePresentationTimeline(Idle(),Attack());
  [Test]public void VisualTimelineMustConsumeLogicalTimeWithoutOwningDamage(){var m=New();m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0);Assert.IsFalse(m.Sample(379,out int frame,out bool attack));Assert.AreEqual(4,frame);Assert.IsTrue(attack);Assert.IsTrue(m.Sample(380,out frame,out attack));Assert.AreEqual(5,frame);Assert.IsFalse(m.Sample(380,out frame,out attack));Assert.IsFalse(m.Sample(1039,out frame,out attack));Assert.AreEqual(11,frame);Assert.IsTrue(attack);m.Sample(1040,out frame,out attack);Assert.AreEqual(0,frame);Assert.IsFalse(attack);}
  [Test]public void CancelBeforeLaunchAndDuplicateOrConflictingInputPreserveReceipt(){var m=New();Assert.IsTrue(m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0));Assert.IsFalse(m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0));var original=m.Capture();Assert.Throws<ArgumentException>(()=>m.Begin(Cue(),KyleFacing.SideOpponentCarriage,0));Assert.IsTrue(JToken.DeepEquals(original,m.Capture()));m.Sample(320,out _,out _);m.Cancel();Assert.IsFalse(m.Sample(380,out _,out _));Assert.AreEqual(-1,m.FireAge(380));}
  [Test]public void OriginalRestoreAndRollbackDoNotDeliverFireTwice(){var m=New();m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0);m.Sample(100,out _,out _);var before=m.Capture();Assert.IsTrue(m.Sample(380,out _,out _));m.Restore(before);Assert.IsFalse(m.Sample(380,out _,out _));var after=m.Capture();var fresh=New();fresh.Restore(after);Assert.IsFalse(fresh.Sample(400,out _,out _));Assert.IsTrue(JToken.DeepEquals(m.Capture()["cues"],fresh.Capture()["cues"]));}
  [Test]public void MalformedRestoreAndClockBackwardsAreAtomic(){var m=New();m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,200);m.Sample(300,out _,out _);var original=m.Capture();var bad=(JObject)original.DeepClone();bad["cues"][0]["startMs"]=201;Assert.Throws<ArgumentException>(()=>m.Restore(bad));Assert.IsTrue(JToken.DeepEquals(original,m.Capture()));Assert.Throws<ArgumentException>(()=>m.Sample(299,out _,out _));Assert.IsTrue(JToken.DeepEquals(original,m.Capture()));}
  [Test]public void AllExposuresAndTerminalHoldUseApprovedTime(){var m=New();m.Begin(Cue(),KyleFacing.SideOpponentCarriage,0);int t=0;var durations=Attack();for(int frame=0;frame<12;frame++){m.Sample(t,out int actual,out bool attack);Assert.AreEqual(frame,actual);Assert.IsTrue(attack);t+=durations[frame];m.Sample(t-1,out actual,out attack);Assert.AreEqual(frame,actual);}Assert.AreEqual(1040,t);}
  [Test]public void PauseSpeedDebtAndPartitionUseOriginalFixedStepOwner(){var clock=new FixedStepDebt(10000);var m=New();m.Begin(Cue(),KyleFacing.RearOpponentCarriage,0);clock.Credit(3790000);while(clock.TryConsumeStep()){}Assert.IsFalse(m.Sample(clock.CompletedSteps,out _,out _));clock.SetPaused(true);clock.Credit(10000000);Assert.IsFalse(m.Sample(clock.CompletedSteps,out _,out _));clock.SetPaused(false);clock.SetSpeed(3);clock.Credit(6666);Assert.AreEqual(0,clock.PendingSteps);clock.Credit(1);Assert.IsTrue(clock.TryConsumeStep());Assert.IsTrue(m.Sample(clock.CompletedSteps,out _,out _));var saved=FixedStepDebt.Restore(clock.Capture());Assert.AreEqual(clock.Capture().DebtHalfTicks,saved.Capture().DebtHalfTicks);var split=New();split.Begin(Cue(),KyleFacing.RearOpponentCarriage,0);split.Sample(100,out _,out _);split.Sample(380,out _,out _);Assert.IsTrue(JToken.DeepEquals(split.Capture(),m.Capture()));}
  [Test]public void RestoringBeforeCueAndReplayingSameCuePreservesAttackPoseWithoutSecondFire(){var m=New();var empty=m.Capture();m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0);m.Sample(380,out _,out _);m.Restore(empty);m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0);Assert.IsFalse(m.Sample(380,out int frame,out bool attacking));Assert.IsTrue(attacking);Assert.AreEqual(5,frame);}
  [Test]public void BoundedIdentitySurvivesRollbackAndNeverChangesActor(){var m=New();var empty=m.Capture();m.Begin(Cue(),KyleFacing.FrontOpponentCarriage,0);m.Sample(380,out _,out _);m.Restore(empty);Assert.Throws<ArgumentException>(()=>m.Begin(Cue(),KyleFacing.SideOpponentCarriage,0));for(int n=1;n<KylePresentationTimeline.Capacity;n++)m.Begin(Cue("cue"+n,"idle"),KyleFacing.FrontOpponentCarriage,n);Assert.Throws<InvalidOperationException>(()=>m.Begin(Cue("overflow"),KyleFacing.FrontOpponentCarriage,1100));Assert.Throws<ArgumentException>(()=>New().Begin(new CombatUnitAnimationState("op_reina",CombatUnitRole.Operator,"attack","wrong"),KyleFacing.FrontOpponentCarriage,0));}
 }
 public class KyleApprovedActorViewTests {
  const string Root="Assets/_LASTRAIL/UI/CombatAnimations/KyleDeliveryV01";GameObject instance;
  [OneTimeSetUp]public void BuildFixture(){var t=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("LastRail.Editor.KyleApprovedDeliveryBuilder")).First(a=>a!=null);t.GetMethod("Build").Invoke(null,null);}
  [SetUp]public void Create()=>instance=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/KyleFourDirectionFixture.prefab"));
  [TearDown]public void Destroy(){if(instance!=null)UnityEngine.Object.DestroyImmediate(instance);}
  KyleApprovedActorView View(int d=1)=>instance.transform.Find("Direction"+d).GetComponent<KyleApprovedActorView>();
  static CombatUnitAnimationState Cue(string id="view-attack")=>new CombatUnitAnimationState("op_kyle",CombatUnitRole.Operator,"attack",id);
  [Test]public void BindRebindFireOnceTerminalExpiryNeverFabricatesHit(){var v=View();int old=0,next=0;v.Bind((id,time)=>old++);v.Bind((id,time)=>{Assert.AreEqual(380,time);next++;});v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,379);Assert.IsFalse(v.ProjectileImage.enabled);v.Render(380);Assert.AreEqual(0,old);Assert.AreEqual(1,next);Assert.IsTrue(v.ProjectileImage.enabled);Assert.IsTrue(v.Flash.enabled);Assert.IsFalse(v.ImpactImage.enabled);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,380);Assert.AreEqual(1,next);v.Render(470);Assert.IsFalse(v.Flash.enabled);v.Render(680);Assert.IsFalse(v.ProjectileImage.enabled);Assert.IsFalse(v.ImpactImage.enabled);v.Render(1040);Assert.AreEqual("idle-01",v.ActorImage.sprite.name);}
  [Test]public void OnlyAuthoritativeHitStartsIndependentEightFrameImpactAtOriginalPoint(){var v=View();v.Bind(null);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,380);Assert.IsTrue(v.AuthoritativeHit("native-hit","view-attack",new Vector2(50,20),400));Assert.IsFalse(v.AuthoritativeHit("native-hit","view-attack",new Vector2(50,20),400));for(int n=0;n<8;n++){v.Render(400+n*20);Assert.IsTrue(v.ImpactImage.enabled);Assert.AreEqual((n+1).ToString("000"),v.ImpactImage.sprite.name);Assert.AreEqual(new Vector2(50,20),v.ImpactImage.rectTransform.anchoredPosition);Assert.IsFalse(v.ProjectileImage.enabled);}v.Render(560);Assert.IsFalse(v.ImpactImage.enabled);Assert.Throws<ArgumentException>(()=>v.AuthoritativeHit("native-hit","view-attack",Vector2.zero,400));}
  [Test]public void DisableUnbindPoolAndCancelPreventLateFireAndFx(){var v=View();int calls=0;v.Bind((id,t)=>calls++);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,320);v.Unbind();v.Render(380);Assert.AreEqual(0,calls);Assert.IsFalse(v.AuthoritativeHit("late","view-attack",Vector2.zero,380));v.Bind((id,t)=>calls++);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,380);Assert.AreEqual(0,calls);v.Present(Cue("next"),KyleFacing.FrontOpponentCarriage,400,780);Assert.AreEqual(1,calls);v.gameObject.SetActive(false);v.Render(800);Assert.AreEqual(1,calls);Assert.IsFalse(v.ProjectileImage.enabled);Assert.IsFalse(v.Flash.enabled);}
  [Test]public void MissDoesNotMakeImpactAndSourceSpritesStayIndependent(){var v=View();v.Bind(null);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,380);var actor=v.ActorImage.sprite;v.AuthoritativeMiss("view-attack");v.Render(400);Assert.IsFalse(v.ProjectileImage.enabled);Assert.IsFalse(v.ImpactImage.enabled);Assert.AreEqual(actor,v.ActorImage.sprite);Assert.AreNotSame(v.ActorImage,v.ProjectileImage);Assert.AreNotSame(v.ProjectileImage,v.ImpactImage);}
  [Test]public void SnapshotRollbackAndRepeatedPauseSampleDoNotReemitFire(){var v=View();int count=0;v.Bind((id,t)=>count++);v.Present(Cue(),KyleFacing.FrontOpponentCarriage,0,100);var snapshot=v.CaptureTimeline();v.Render(380);Assert.AreEqual(1,count);v.RestoreTimeline(snapshot);v.Render(380);v.Render(380);Assert.AreEqual(1,count);}
  [Test]public void CancelRejectsLateHitAndOlderHitCannotTerminateNewShot(){var v=View();v.Bind(null);v.Present(Cue("A"),KyleFacing.FrontOpponentCarriage,0,380);v.Cancel();Assert.IsFalse(v.AuthoritativeHit("late-A","A",Vector2.zero,400));v.Render(400);Assert.IsFalse(v.ImpactImage.enabled);v.Present(Cue("B"),KyleFacing.FrontOpponentCarriage,500,880);Assert.IsTrue(v.ProjectileImage.enabled);Assert.IsFalse(v.AuthoritativeHit("late-A","A",Vector2.zero,400));v.Render(900);Assert.IsTrue(v.ProjectileImage.enabled);}
  [Test]public void OlderValidHitNeverStopsNewAttackProjectile(){var v=View();v.Bind(null);v.Present(Cue("A"),KyleFacing.FrontOpponentCarriage,0,380);v.Present(Cue("B"),KyleFacing.FrontOpponentCarriage,500,880);Assert.IsTrue(v.AuthoritativeHit("hit-A","A",new Vector2(20,30),900));v.Render(900);Assert.IsTrue(v.ProjectileImage.enabled);Assert.IsTrue(v.ImpactImage.enabled);v.AuthoritativeMiss("B");Assert.IsFalse(v.AuthoritativeHit("contradict-miss","B",Vector2.zero,910));}
  [Test]public void PresentWithInvalidFutureOrBackwardsClockDoesNotPublishAnyCue(){var v=View();v.Bind(null);v.Present(Cue("A"),KyleFacing.FrontOpponentCarriage,0,500);var before=v.CaptureTimeline();Assert.Throws<ArgumentException>(()=>v.Present(Cue("B"),KyleFacing.FrontOpponentCarriage,600,550));Assert.IsTrue(JToken.DeepEquals(before,v.CaptureTimeline()));v.Render(550);}
  [Test]public void RebindingAfterTwoCuesRejectsOldBindingLateHit(){var v=View();v.Bind(null);v.Present(Cue("A"),KyleFacing.FrontOpponentCarriage,0,380);v.Present(Cue("B"),KyleFacing.FrontOpponentCarriage,500,880);v.Unbind();v.Bind(null);Assert.IsFalse(v.AuthoritativeHit("old-binding-A","A",Vector2.zero,900));v.Render(900);Assert.IsFalse(v.ImpactImage.enabled);}
  [Test]public void DelayedOldMissClosesOnlyOldCue(){var v=View();v.Bind(null);v.Present(Cue("A"),KyleFacing.FrontOpponentCarriage,0,380);v.Present(Cue("B"),KyleFacing.FrontOpponentCarriage,500,880);v.AuthoritativeMiss("A");Assert.IsFalse(v.AuthoritativeHit("invalid-A","A",Vector2.zero,900));v.Render(900);Assert.IsTrue(v.ProjectileImage.enabled);}
  [Test]public void GraphicsFixtureRendersAllFourDirectionsAndSeparateEffects(){if(SystemInfo.graphicsDeviceType==GraphicsDeviceType.Null)Assert.Ignore("Graphics run required; never Camera.Render under NullGfxDevice");var canvasGo=new GameObject("Kyle 2D native graphical fixture",typeof(RectTransform),typeof(Canvas));var cameraGo=new GameObject("Fixture camera",typeof(Camera));var rt=new RenderTexture(960,360,24);Texture2D pixels=null;var previous=RenderTexture.active;try{var canvas=canvasGo.GetComponent<Canvas>();canvas.renderMode=RenderMode.WorldSpace;canvasGo.GetComponent<RectTransform>().sizeDelta=new Vector2(960,360);instance.transform.SetParent(canvasGo.transform,false);var camera=cameraGo.GetComponent<Camera>();camera.orthographic=true;camera.orthographicSize=180;camera.transform.position=new Vector3(0,30,-10);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.12f,.15f,.19f,1);camera.targetTexture=rt;canvas.worldCamera=camera;for(int d=1;d<=4;d++){var v=View(d);v.Bind(null);v.Present(Cue("direction-"+d),(KyleFacing)d,0,380);}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;pixels=new Texture2D(960,360,TextureFormat.RGBA32,false);pixels.ReadPixels(new Rect(0,0,960,360),0,0);pixels.Apply();var run=Environment.GetEnvironmentVariable("LASTRAIL_KYLE_VISUAL_RUN")??"Visual01";if(!run.All(ch=>char.IsLetterOrDigit(ch)||ch=='_'))throw new ArgumentException("Safe visual run required");var path="D:/Project/LASTRAIL/QA/KyleUnity-20261014/"+run;Directory.CreateDirectory(path);File.WriteAllBytes(path+"/four-directions-fire-380ms.png",pixels.EncodeToPNG());for(int d=1;d<=4;d++){var v=View(d);v.Render(400);v.AuthoritativeHit("fixture-hit-"+d,"direction-"+d,new Vector2(30,60),400);v.Render(400);}Canvas.ForceUpdateCanvases();camera.Render();pixels.ReadPixels(new Rect(0,0,960,360),0,0);pixels.Apply();File.WriteAllBytes(path+"/independent-hit-400ms.png",pixels.EncodeToPNG());Assert.Greater(pixels.GetPixels32().Count(c=>c.r>100||c.g>100||c.b>100),500,"Real native UI pixels present");}finally{RenderTexture.active=previous;cameraGo.GetComponent<Camera>().targetTexture=null;if(pixels!=null)UnityEngine.Object.DestroyImmediate(pixels);rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(cameraGo);UnityEngine.Object.DestroyImmediate(canvasGo);instance=null;}}
 }
}
